<script setup lang="ts">
import { onMounted,ref } from 'vue';
import { RpcEvent,type BusinessAuditView,type BusinessEmployeeView,type BusinessPayrollResult,type BusinessPurchaseResult,type BusinessRestockResult,type BusinessSaleResult,type BusinessTreasuryResult,type BusinessUpgradeView,type BusinessView } from '@eclipse/shared';import { rpc } from '../core/rpc';import StorePanel from './StorePanel.vue';
type Mode='owned'|'catalog';const mode=ref<Mode>('owned'),owned=ref<BusinessView[]>([]),catalog=ref<BusinessView[]>([]),busy=ref(false),error=ref(''),notice=ref(''),selected=ref<string|null>(null);const amounts=ref<Record<string,string>>({}),quantities=ref<Record<string,string>>({}),markups=ref<Record<string,string>>({});const employees=ref<BusinessEmployeeView[]>([]),upgrades=ref<BusinessUpgradeView[]>([]),audit=ref<BusinessAuditView[]>([]),hireTarget=ref(''),editSalary=ref<Record<number,string>>({}),editRole=ref<Record<number,'employee'|'manager'>>({});
const money=(v:string|null|undefined)=>Number(v??0).toLocaleString('ru-RU',{maximumFractionDigits:2});const load=async()=>{const[o,c]=await Promise.all([rpc<BusinessView[]>(RpcEvent.BusinessOwned),rpc<BusinessView[]>(RpcEvent.BusinessCatalog)]);if(o.ok)owned.value=o.data;if(c.ok)catalog.value=c.data;};
const run=async<T>(event:string,payload:unknown,message=''):Promise<T|null>=>{if(busy.value)return null;busy.value=true;error.value='';notice.value='';try{const r=await rpc<T>(event,payload);if(!r.ok){error.value=r.code;return null;}if(message)notice.value=message;return r.data;}finally{busy.value=false;}};
const buy=async(id:string)=>{if(await run<BusinessPurchaseResult>(RpcEvent.BusinessBuy,{businessId:id},'Бизнес приобретён'))await load();};const sell=async(id:string)=>{if(await run<BusinessSaleResult>(RpcEvent.BusinessSell,{businessId:id},'Бизнес продан государству'))await load();};const transfer=async(event:string,b:BusinessView)=>{if(await run<BusinessTreasuryResult>(event,{businessId:b.id,amount:amounts.value[b.id]??''},'Баланс обновлён')){amounts.value[b.id]='';await load();}};const restock=async(b:BusinessView)=>{if(await run<BusinessRestockResult>(RpcEvent.BusinessRestock,{businessId:b.id,quantity:Number(quantities.value[b.id]??0)},'Поставка принята'))await load();};const markup=async(b:BusinessView)=>{if(await run<BusinessView>(RpcEvent.BusinessSetMarkup,{businessId:b.id,markupPercent:Number(markups.value[b.id]??b.markupPercent)},'Наценка изменена'))await load();};
const manage=async(id:string)=>{selected.value=selected.value===id?null:id;if(!selected.value)return;const[e,u,a]=await Promise.all([rpc<BusinessEmployeeView[]>(RpcEvent.BusinessEmployees,{businessId:id}),rpc<BusinessUpgradeView[]>(RpcEvent.BusinessUpgrades,{businessId:id}),rpc<BusinessAuditView[]>(RpcEvent.BusinessAudit,{businessId:id})]);employees.value=e.ok?e.data:[];upgrades.value=u.ok?u.data:[];audit.value=a.ok?a.data:[];for(const x of employees.value){editSalary.value[x.characterId]=x.salary;editRole.value[x.characterId]=x.role;}};
const hire=async(id:string)=>{const r=await run<BusinessEmployeeView[]>(RpcEvent.BusinessHire,{businessId:id,characterId:Number(hireTarget.value)},'Сотрудник принят');if(r){employees.value=r;hireTarget.value='';}};const updateEmployee=async(id:string,e:BusinessEmployeeView)=>{const r=await run<BusinessEmployeeView[]>(RpcEvent.BusinessEmployeeUpdate,{businessId:id,characterId:e.characterId,role:editRole.value[e.characterId]??e.role,salary:editSalary.value[e.characterId]??e.salary},'Данные сотрудника изменены');if(r)employees.value=r;};const fire=async(id:string,target:number)=>{const r=await run<BusinessEmployeeView[]>(RpcEvent.BusinessFire,{businessId:id,characterId:target},'Сотрудник уволен');if(r)employees.value=r;};const payroll=async(id:string)=>{const r=await run<BusinessPayrollResult>(RpcEvent.BusinessPayroll,{businessId:id},'Зарплаты выплачены');if(r){notice.value=`Выплачено ${r.paidCount} сотрудникам: $${money(r.totalPaid)}`;await load();}};const upgrade=async(id:string,key:BusinessUpgradeView['key'])=>{const r=await run<BusinessUpgradeView[]>(RpcEvent.BusinessUpgradeBuy,{businessId:id,key},'Улучшение приобретено');if(r){upgrades.value=r;await load();}};
onMounted(()=>void load());
</script>
<template><section class="business-panel"><div class="toolbar"><div><button :class="{active:mode==='owned'}" @click="mode='owned'">Мои бизнесы</button><button :class="{active:mode==='catalog'}" @click="mode='catalog'">Каталог</button></div><button @click="load">Обновить</button></div><p v-if="error" class="msg error">{{error}}</p><p v-if="notice" class="msg ok">{{notice}}</p><div v-if="mode==='catalog'" class="grid"><article v-for="b in catalog" :key="b.id"><header><div><small>{{b.kind}}</small><h3>{{b.name}}</h3></div><strong>${{money(b.price)}}</strong></header><p>Склад {{b.stock}} / {{b.stockCapacity}} · наценка {{b.markupPercent}}%</p><button v-if="!b.owned" @click="buy(b.id)">Купить</button><span v-else>{{b.ownedByMe?'Принадлежит вам':'Уже куплен'}}</span></article></div>
<div v-else class="grid"><article v-for="b in owned" :key="b.id"><header><div><small>{{b.kind}}</small><h3>{{b.name}}</h3></div><strong>${{money(b.price)}}</strong></header><div class="stats"><span>Банк <b>${{money(b.bankBalance)}}</b></span><span>Касса <b>${{money(b.cashBalance)}}</b></span><span>Склад <b>{{b.stock}} / {{b.stockCapacity}}</b></span></div><div class="row"><input v-model="amounts[b.id]" placeholder="Сумма"><button @click="transfer(RpcEvent.BusinessDeposit,b)">Внести</button><button @click="transfer(RpcEvent.BusinessWithdraw,b)">Вывести</button></div><div class="row"><input v-model="quantities[b.id]" placeholder="Товар"><button @click="restock(b)">Закупить по ${{money(b.wholesaleUnitCost)}}</button></div><div class="row"><input v-model="markups[b.id]" :placeholder="String(b.markupPercent)+'%'"><button @click="markup(b)">Наценка</button><button @click="manage(b.id)">Управление</button></div><button class="danger" @click="sell(b.id)">Продать государству</button>
<div v-if="selected===b.id" class="manage"><h4>Сотрудники</h4><div class="row"><input v-model="hireTarget" placeholder="Static ID"><button @click="hire(b.id)">Принять</button><button @click="payroll(b.id)">Выплатить зарплаты</button></div><div v-for="e in employees" :key="e.characterId" class="employee"><b>#{{e.characterId}} {{e.name}}</b><select v-model="editRole[e.characterId]"><option value="employee">Сотрудник</option><option value="manager">Менеджер</option></select><input v-model="editSalary[e.characterId]" placeholder="Зарплата"><button @click="updateEmployee(b.id,e)">Сохранить</button><button class="danger" @click="fire(b.id,e.characterId)">Уволить</button></div><h4>Улучшения</h4><div class="upgrades"><button v-for="u in upgrades" :key="u.key" :disabled="!u.nextPrice" @click="upgrade(b.id,u.key)">{{u.key}} · ур. {{u.level}} <span v-if="u.nextPrice">→ ${{money(u.nextPrice)}}</span><span v-else>MAX</span></button></div><h4>Последние действия</h4><div class="audit"><span v-for="a in audit.slice(0,12)" :key="a.id">{{new Date(a.createdAt).toLocaleString('ru-RU')}} · {{a.action}} <b v-if="a.targetCharacterId">#{{a.targetCharacterId}}</b></span></div></div></article><p v-if="!owned.length" class="empty">У вас пока нет бизнеса.</p></div><StorePanel/></section></template>
<style scoped>.business-panel{display:grid;gap:14px}.toolbar,.toolbar>div,.row,.employee,.upgrades{display:flex;gap:7px;align-items:center}.toolbar{justify-content:space-between}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}article{padding:16px;border:1px solid var(--e-border);border-radius:14px;background:var(--e-surface-1)}header{display:flex;justify-content:space-between}h3,h4{margin:4px 0}small{color:var(--e-accent)}p,span{color:var(--e-text-muted);font-size:12px}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:7px;margin:12px 0}.stats span{padding:8px;background:var(--e-surface-2);border-radius:9px}.stats b{display:block;color:var(--e-text-primary)}button,input,select{border:1px solid var(--e-border);border-radius:9px;background:var(--e-surface-2);color:var(--e-text-primary);padding:9px}.row{margin:8px 0}.row input{min-width:0;flex:1}.manage{display:grid;gap:7px;margin-top:12px;padding-top:10px;border-top:1px solid var(--e-border)}.employee{flex-wrap:wrap}.employee b{min-width:150px}.employee input{width:100px}.upgrades{flex-wrap:wrap}.audit{display:grid;max-height:130px;overflow:auto;gap:3px}.danger,.error{color:#ff8585}.ok{color:#7dde9f}.msg{padding:9px}.empty{grid-column:1/-1;text-align:center}button.active{border-color:var(--e-accent)}</style>